CREATE DATABASE phone_shop; USE phone_shop;
CREATE TABLE customers (customer_id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) UNIQUE, email VARCHAR(255) UNIQUE, password VARCHAR(255), phone_number VARCHAR(30), address VARCHAR(255), profile_picture VARCHAR(255), province_city VARCHAR(100), district VARCHAR(100), street VARCHAR(100), house_no VARCHAR(50), is_default_address TINYINT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin (admin_id INT AUTO_INCREMENT PRIMARY KEY, adminname VARCHAR(100), email VARCHAR(255), password VARCHAR(255), role ENUM('support','manager','admin') NOT NULL DEFAULT 'support');
CREATE TABLE brands (brand_id INT AUTO_INCREMENT PRIMARY KEY, brand_name VARCHAR(100), img VARCHAR(255));
CREATE TABLE categories (category_id INT AUTO_INCREMENT PRIMARY KEY, category_name VARCHAR(100));
CREATE TABLE phones (phone_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), description TEXT, category_id INT, brand_id INT, release_date DATE);
CREATE TABLE phone_variants (idphone_variants INT AUTO_INCREMENT PRIMARY KEY, phone_id INT, color VARCHAR(50), stock INT);
CREATE TABLE specifications (spec_id INT AUTO_INCREMENT PRIMARY KEY, phone_variant_id INT, screen_size VARCHAR(50), processor VARCHAR(100), ram VARCHAR(20), storage VARCHAR(20), battery VARCHAR(50), camera VARCHAR(100), price DECIMAL(10,2), stock INT, reserved_stock INT DEFAULT 0);
CREATE TABLE productimage (id INT AUTO_INCREMENT PRIMARY KEY, phone_variant_id INT, image VARCHAR(255));
CREATE TABLE promotions (promo_id INT AUTO_INCREMENT PRIMARY KEY, spec_id INT, promo_name VARCHAR(255), discount_percentage DECIMAL(5,2), start_date DATE, end_date DATE, status VARCHAR(20));
CREATE TABLE orders (order_id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT, order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, status ENUM('pending','completed','shipping','delivered','canceled') DEFAULT 'pending', recipient_name VARCHAR(100), delivery VARCHAR(50), payment VARCHAR(50), payment_verified TINYINT DEFAULT 0, location VARCHAR(255), total_amount DECIMAL(12,2));
CREATE TABLE order_items (order_item_id INT AUTO_INCREMENT PRIMARY KEY, order_id INT, spec_id INT, quantity INT, reserved_quantity INT DEFAULT 0, amount DECIMAL(12,2));
CREATE TABLE product_reviews (review_id INT AUTO_INCREMENT PRIMARY KEY, spec_id INT, customer_id INT, rating INT, title VARCHAR(255), comment TEXT, helpful_count INT DEFAULT 0, unhelpful_count INT DEFAULT 0, is_verified_purchase BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE review_votes (vote_id INT AUTO_INCREMENT PRIMARY KEY, review_id INT, customer_id INT, vote_type ENUM('helpful','unhelpful'), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE browsing_history (history_id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT, spec_id INT, viewed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE chat_conversations (conversation_id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT, admin_id INT, room_code VARCHAR(50) UNIQUE, status ENUM('open','closed','waiting') DEFAULT 'waiting', started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, closed_at TIMESTAMP NULL);
CREATE TABLE chat_messages (message_id INT AUTO_INCREMENT PRIMARY KEY, conversation_id INT, sender_id INT, sender_type ENUM('customer','admin'), message TEXT, attachment_url VARCHAR(500), is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

